{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "table"
  },
  "width": 300,
  "height": 300,
  "mark": {
    "type": "bar"
  },
  "encoding": {
    "x": {
      "field": "query",
      "type": "nominal",
      "title": null,
      "sort": {
        "field": "q_number"
      }
    },
    "y": {
      "field": "median_ms",
      "type": "quantitative",
      "title": "median ms"
    },
    "xOffset": {
      "field": "engine",
      "type": "nominal"
    },
    "color": {
      "field": "engine",
      "type": "nominal"
    },
    "column": {
      "field": "node",
      "type": "nominal",
      "title": null
    },
    "tooltip": [
      {
        "field": "node"
      },
      {
        "field": "query"
      },
      {
        "field": "engine"
      },
      {
        "field": "config_name"
      },
      {
        "field": "median_ms"
      },
      {
        "field": "n_runs"
      }
    ],
    "opacity": {
      "field": "config_name",
      "type": "nominal",
      "title": "config",
      "scale": {
        "range": [
          1.0,
          0.55,
          0.3
        ]
      }
    }
  },
  "config": {
    "background": null,
    "font": "ui-monospace, Menlo, Consolas, monospace",
    "axis": {
      "labelFontSize": 11,
      "titleFontSize": 12,
      "grid": true,
      "gridColor": "#8884",
      "domainColor": "#8886",
      "tickColor": "#8886"
    },
    "legend": {
      "labelFontSize": 11,
      "titleFontSize": 12
    },
    "view": {
      "stroke": "transparent"
    },
    "range": {
      "category": [
        "#0b5",
        "#c50",
        "#06c",
        "#a2b",
        "#888",
        "#c33"
      ]
    }
  }
}

