{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "table"
  },
  "facet": {
    "row": {
      "field": "node",
      "type": "nominal",
      "title": null
    },
    "column": {
      "field": "query",
      "type": "nominal",
      "title": null,
      "sort": {
        "field": "q_number"
      }
    }
  },
  "spec": {
    "width": 190,
    "height": 160,
    "mark": {
      "type": "line",
      "point": true
    },
    "encoding": {
      "x": {
        "field": "threads",
        "type": "quantitative",
        "scale": {
          "type": "log",
          "base": 2
        },
        "title": "threads"
      },
      "y": {
        "field": "median_ms",
        "type": "quantitative",
        "title": "median ms"
      },
      "color": {
        "field": "engine",
        "type": "nominal"
      },
      "strokeDash": {
        "field": "sf_label",
        "type": "nominal",
        "title": "scale"
      },
      "tooltip": [
        {
          "field": "node"
        },
        {
          "field": "query"
        },
        {
          "field": "engine"
        },
        {
          "field": "config_name"
        },
        {
          "field": "sf_label"
        },
        {
          "field": "threads"
        },
        {
          "field": "median_ms"
        },
        {
          "field": "n_runs"
        }
      ],
      "opacity": {
        "field": "config_name",
        "type": "nominal",
        "title": "config",
        "scale": {
          "range": [
            1.0,
            0.55,
            0.3
          ]
        }
      },
      "detail": {
        "field": "build_event_id",
        "type": "nominal"
      }
    }
  },
  "config": {
    "background": null,
    "font": "ui-monospace, Menlo, Consolas, monospace",
    "axis": {
      "labelFontSize": 11,
      "titleFontSize": 12,
      "grid": true,
      "gridColor": "#8884",
      "domainColor": "#8886",
      "tickColor": "#8886"
    },
    "legend": {
      "labelFontSize": 11,
      "titleFontSize": 12
    },
    "view": {
      "stroke": "transparent"
    },
    "range": {
      "category": [
        "#0b5",
        "#c50",
        "#06c",
        "#a2b",
        "#888",
        "#c33"
      ]
    }
  },
  "resolve": {
    "scale": {
      "x": "independent"
    }
  }
}

